#include <cstdint>
#include <cstddef>
#include <vector>
#include <random>
#include <cstdio>
#include <cstdlib>
#include <bit>
using U=std::uint32_t;using W=std::uint64_t;
static std::uint64_t checks=0,cases=0;
static void check(bool x){++checks;if(!x)std::abort();}
static void transform(std::vector<W>&flags,U m){
 for(W&x:flags){x|=(x<<1)&UINT64_C(0xaaaaaaaaaaaaaaaa);x|=(x<<2)&UINT64_C(0x8888888888888888);x|=(x<<4)&UINT64_C(0x8080808080808080);x|=(x<<8)&UINT64_C(0x8000800080008000);x|=(x<<16)&UINT64_C(0x8000000080000000);x|=(x<<32)&UINT64_C(0x8000000000000000);}
 const U complete=m/64;
 for(U b=1;b<=complete;++b){const U parent=b+(b&(U(0)-b));if(parent<=complete)flags[parent-1]|=flags[b-1]&UINT64_C(0x8000000000000000);}
 if(m%64)flags.back()&=(W(1)<<(m%64))-1;
}
static void verify(U m,const std::vector<U>&points){
 ++cases;std::vector<W>actual((m+63)/64,0),expected=actual;
 for(U c:points){actual[(c-1)/64]|=W(1)<<((c-1)%64);for(U k=c;k<=m;k+=k&(U(0)-k))expected[(k-1)/64]|=W(1)<<((k-1)%64);}
 transform(actual,m);check(actual.size()==expected.size());for(std::size_t i=0;i<actual.size();++i)check(actual[i]==expected[i]);
}
int main(){
 verify(0,{});for(U m=1;m<=512;++m)for(U c=1;c<=m;++c)verify(m,{c});
 for(U m=1;m<=128;++m)for(U a=1;a<=m;++a)for(U b=a;b<=m;++b)verify(m,{a,b});
 std::mt19937_64 rng(5239701);for(U m:{U(63),U(64),U(65),U(127),U(128),U(129),U(8191),U(8192),U(8193),U(999999),U(1000000)})for(U count:{U(0),U(1),U(8),U(128),U(10000)}){std::vector<U>points;for(U j=0;j<count;++j)points.push_back(U(rng()%m)+1);verify(m,points);}
 std::printf("{\"independent_flag_cases\":%ju,\"assertions\":%ju,\"status\":\"pass\"}\n",std::uintmax_t(cases),std::uintmax_t(checks));
}
